import sys,numpy as np
from PIL import Image
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
r=Robot();o=r.get_obs(cameras=['front','side','top'],include_depth=True,video='frames')
for c in o.last:Image.fromarray(o.last[c]).save('/app/output/depthnow_'+c+'.png');np.save('/app/output/depthnow_'+c+'.npy',o.depth[c][0].astype(np.float32))
K=230.517855
cams={'front':(np.array([-.034,-.95,.95]),np.array([[1,0,0],[0,.31622776,-.94868332],[0,.94868332,.31622776]])),'side':(np.array([.95,.116,.85]),np.array([[0,-.2544933,.9670745],[1,0,0],[0,.9670745,.2544933]])),'top':(np.array([.034,.12,1.65]),np.array([[-1,0,0],[0,-.99983478,.01817881],[0,.01817881,.99983478]]))}
def back(c,u,v):
 o,Rgl=cams[c];R=Rgl@np.diag([1,-1,-1]);d=float(oD[c][v,u]);ray=np.array([(u-160)/K,(v-120)/K,1]);return d,o+R@ray*d
# hold depths
oD={c:o.depth[c][0] for c in cams}
for c, pts in {'front':[(165,105),(170,110),(175,115),(180,130),(180,132),(170,132),(160,132)],'side':[(125,105),(135,110),(140,120),(145,130),(150,132),(160,132)],'top':[(150,120),(155,124),(160,128),(165,128)]}.items():
 print('\n',c)
 for uv in pts:print(uv,back(c,*uv))
print('q',o.meta['proprio']['now'][:7],'task',o.meta['task']['goal_index'])
